'సేవ్ చేసిన పాస్వర్డ్‌లు ఎన్‌క్రిప్ట్ చేయబడతాయి.',
'LessPass లాంటి పాస్వర్డ్‌లే.',
'కొత్తగా సేవ్ చేసిన పాస్వర్డ్ ఎంతకాలం ఉంటుంది. ఏ నమోదులోనైనా దీన్ని మార్చవచ్చు.',
'సేవ్ చేసిన నమోదు',
'మరిన్ని చర్యలు',
'యాప్‌ను లాక్ చేయి',
'మీ ఫోన్ సొంత స్క్రీన్ లాక్ ఉంటే యాప్‌ను దాని వెనుక లాక్ చేస్తుంది. మీ ఫోనే దాన్ని తనిఖీ చేస్తుంది — ఈ యాప్ దాన్ని ఎప్పుడూ చూడదు.',
'పాస్వర్డ్‌లో ఎన్ని అక్షరాలు ఉంటాయి.',
'వేరే పాస్వర్డ్ కోసం దీన్ని మార్చండి.',
'పాస్వర్డ్ ఏ రకమైన అక్షరాలతో తయారవుతుంది. మీరు ఎంచుకున్న ప్రతి రకం కనీసం ఒకసారి వాడబడుతుంది.',
'గడువు',
'సైట్, లాగిన్ మరియు పాస్వర్డ్',
'పైన పిన్ చేయి లేదా పిన్ తీసివేయి',
'కొత్త పరికరానికి బ్యాకప్ ఎగుమతి చేయండి.',
'నేపథ్యంలోనూ లాక్ చేయి',
'ఆన్ ఉన్నప్పుడు, వేరే యాప్‌కు వెళ్లి తిరిగి వచ్చినప్పుడు మీ స్క్రీన్ లాక్ మళ్లీ అడుగుతుంది. ఆఫ్ ఉన్నప్పుడు, యాప్ కొత్తగా మొదలైనప్పుడే అడుగుతుంది.',
